script:
document.addEventListener("DOMContentLoaded", function () {
  const form = document.getElementById("reset_form");

  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();

      const new_password = form.querySelector('input[name="new_password"]').value;
      const confirm_password = form.querySelector('input[name="confirm_password"]').value;
      const csrfToken = page_data.csrf_token;

      const params = new URLSearchParams(window.location.search);
    const key = params.get("key");

    const payload = {
      key: key,
      old_password: "",
      new_password: new_password,
      confirm_password: confirm_password,
      logout_all_seassions: 1
    };


      fetch("/api/method/frappe.core.doctype.user.user.update_password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          'x-frappe-csrf-token': csrfToken,
        },
        body: JSON.stringify(payload)
      })
      .then(response => response.json())
        .then(data => {
          if (data.message) {
            Toastify({
              text: `${data.message}`,
              close: true,
              gravity: "top",
              position: "center",
              stopOnFocus: true,
              style: {
                background: "linear-gradient(to right, #ff416c, #ff4b2b)", // red tone
              }
            }).showToast();
          } else {
            Toastify({
              text: "✅ Reset successfull!",
              close: true,
              gravity: "top",
              position: "center",
              stopOnFocus: true,
              style: {
                background: "var(--primary-color)",
              }
            }).showToast();
          }
        })
        .catch(error => {
          console.error("Error:", error);
          Toastify({
            text: "⚠️ Network error. Please try again.",
            close: true,
            gravity: "top",
            position: "center",
            stopOnFocus: true,
            style: {
              background: "linear-gradient(to right, #ff416c, #ff4b2b)",
            }
          }).showToast();
        });
    });
  }
});
